methods.downloadDocuments:
downloadDocuments() {
                    this.download_loading = true;
                    axios.get(this.attachable.url + '/download-documents')
                        .then((response) => {
                            let link = document.createElement('a');
                            link.href = response.data.url;
                            document.body.appendChild(link);
                            link.click();
                            setTimeout(() => {
                                document.body.removeChild(link);
                            }, 100);
                        })
                        .catch((e) => {
                            Alert.alert('There was an error compiling the documents');
                        })
                        .then(() => {
                            this.download_loading = false;
                        })
                }

methods.fetchAgendaAggregate:
fetchAgendaAggregate(force_rebuild, is_poll) {
                    this.status = 'processing';
                    clearTimeout(this.boardPacketPollTimer);
                    let url = this.meeting.url + '/agenda/documents/info?packet=true';
                    if (this.current_date)
                        url += `&date=${this.current_date.id}`;

                    if (force_rebuild)
                        url += '&force_rebuild=true';

                    if (is_poll)
                        url += '&poll=1';

                    axios.get(url)
                        .then((response) => {
                            if (response.data.build_status === 'success') {
                                this.boardPacketStatus = 'success';
                                this.componentKey++;
                            }
                            else if (response.data.build_status === 'error') {
                                this.boardPacketStatus = 'error';
                                this.componentKey++;
                            }
                            else if (response.data.build_status === 'processing') {
                                // Poll while the build runs — the Echo
                                // broadcast also refreshes on completion, but
                                // must not be the only way out of the spinner.
                                this.boardPacketPollTimer = setTimeout(() => this.fetchAgendaAggregate(false, true), 5000);
                            }
                        });
                }

methods.fetchAssignables:
fetchAssignables() {
                    return axios.post(Boardable.data_url('assignables'), {
                        model_type: 'meetingCollaborators',
                        model_id: "526577"
                    }).then( response => {
                            this.assignableUsers = response.data.assignable_users || []
                            this.assignableGroups = response.data.assignable_groups || []
                            this.assignableNonInvitees = response.data.assignable_non_invitees || []
                    })
                }

methods.handleNumUploadsChanged:
handleNumUploadsChanged(d, newItems) {
                    this.num_agenda_uploads += d;
                    this.agendaAttachments = newItems;
                }
